import styled from '@emotion/styled';

import { DDT_COLORS, DDT_SPACING } from '../../DrillDownTable.styles';

export const DDTHeaderRow = styled.div({
  display: 'flex',
  flexDirection: 'row',
});

export const DDTAxisHeader = styled.div({
  flexGrow: 0,
  flexShrink: 0,
  flexBasis: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  width: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  minWidth: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  maxWidth: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  display: 'flex',
  flexDirection: 'column',
  boxSizing: 'border-box',
});

export const DDTAxisHeaderTop = styled.div({
  height: DDT_SPACING.headerGroupHeight,
  backgroundColor: DDT_COLORS.background.groupHeader,
  borderRight: `1px solid ${DDT_COLORS.border.header}`,
  boxSizing: 'border-box',
});

export const DDTAxisHeaderBottom = styled.div({
  height: DDT_SPACING.headerSubHeight,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  padding: '0 16px',
  backgroundColor: DDT_COLORS.background.accent,
  borderRight: `1px solid ${DDT_COLORS.border.header}`,
  borderTop: `1px solid ${DDT_COLORS.border.header}`,
  boxSizing: 'border-box',
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 400,
  fontSize: '14px',
  color: DDT_COLORS.text.primary,
});

export const DDTGroupsWrapper = styled.div({
  display: 'flex',
  flexDirection: 'row',
  flex: 1,
  minWidth: 0,
});

interface DDTGroupHeaderProps {
  $isLast?: boolean;
}

export const DDTGroupHeader = styled.div<DDTGroupHeaderProps>(({ $isLast }) => ({
  flex: 1,
  display: 'flex',
  flexDirection: 'column',
  borderRight: `1px solid ${DDT_COLORS.border.group}`,
  boxSizing: 'border-box',
  overflow: 'hidden',
  ...($isLast && { borderRight: 'none' }),
}));

export const DDTGroupTitle = styled.div({
  height: DDT_SPACING.headerGroupHeight,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: '6px',
  padding: '0 12px',
  backgroundColor: DDT_COLORS.background.groupHeader,
  boxSizing: 'border-box',
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 400,
  fontSize: '14px',
  color: DDT_COLORS.text.primary,
});

export const DDTGroupTitleUnit = styled.span({
  fontWeight: 400,
  fontSize: '11px',
  color: DDT_COLORS.text.secondary,
});

export const DDTSubColumnsRow = styled.div({
  display: 'flex',
  flexDirection: 'row',
  flex: 1,
  height: DDT_SPACING.headerSubHeight,
});

interface DDTSubColumnHeaderProps {
  $isLast?: boolean;
}

export const DDTSubColumnHeader = styled.div<DDTSubColumnHeaderProps>(
  ({ $isLast }) => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '4px',
    padding: '0 8px',
    backgroundColor: DDT_COLORS.background.accent,
    borderTop: `1px solid ${DDT_COLORS.border.header}`,
    borderRight: `1px solid ${DDT_COLORS.border.header}`,
    boxSizing: 'border-box',
    fontFamily: "'Work Sans', sans-serif",
    fontWeight: 400,
    fontSize: '14px',
    color: DDT_COLORS.text.primary,
    ...($isLast && { borderRight: 'none' }),
  }),
);

export const DDTInfoIconWrapper = styled.div({
  display: 'inline-flex',
  alignItems: 'center',
  width: '16px',
  height: '16px',
  flexShrink: 0,
  '& svg': {
    width: '16px',
    height: '16px',
    '& path': {
      fill: '#999999',
    },
  },
});
